def transform(grid):
    h, w = len(grid), len(grid[0])
    color = next(v for row in grid for v in row if v)
    out = [row[:] for row in grid]

    # Fill between diagonal boundary markers on each row. Pair markers
    # whose positions continue diagonally from markers on neighboring rows.
    for r in range(h):
        marks = [c for c, v in enumerate(grid[r]) if v == color]
        pairs = []
        for i, a in enumerate(marks):
            for b in marks[i + 1:]:
                if (b - a) % 2 == 0:
                    mid = (a + b) // 2
                    # Require the two endpoints to be supported by
                    # diagonal boundary markers on an adjacent row.
                    supported = r == 0 or r == h - 1
                    for rr in (r - 1, r + 1):
                        if 0 <= rr < h:
                            nxt = {c for c, v in enumerate(grid[rr]) if v == color}
                            if a - 1 in nxt or a + 1 in nxt:
                                if b - 1 in nxt or b + 1 in nxt:
                                    supported = True
                    if supported:
                        pairs.append((a, b))
        # Prefer close pairs so separate shapes are not bridged.
        used = set()
        for a, b in sorted(pairs, key=lambda p: p[1] - p[0]):
            if a not in used and b not in used:
                for c in range(a + 1, b):
                    if out[r][c] == 0:
                        out[r][c] = 2
                used.update((a, b))
    return out
